<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { Activity, ArrowDown, ArrowUp, ArrowUpRight, Camera, Check, ChevronRight, CircleHelp, Database, Download, Folder, Gauge, Globe2, HardDrive, LayoutDashboard, LogOut, Map, Menu, Monitor, MoreHorizontal, Radio, RefreshCw, Search, Settings2, ShieldCheck, SlidersHorizontal, Sun, Usb, Users, Video, Wifi, X } from '@lucide/vue'
import ObservationCard from './components/ObservationCard.vue'
import RadioMap from './components/RadioMap.vue'
import { api, bytes, date, setCSRF, type Capability, type FileEntry, type Settings, type Summary } from './services/api'

const nav=[{id:'dashboard',label:'ダッシュボード',icon:LayoutDashboard,group:'OVERVIEW'},{id:'internet',label:'インターネット',icon:Globe2,group:'NETWORK'},{id:'wifi',label:'Wi-Fi / AP',icon:Wifi},{id:'clients',label:'接続端末',icon:Users},{id:'traffic',label:'通信量',icon:Activity},{id:'camera',label:'カメラ',icon:Camera,group:'DEVICE'},{id:'recordings',label:'録画ライブラリ',icon:Video},{id:'storage',label:'SDカード',icon:HardDrive},{id:'trips',label:'走行履歴・電波マップ',icon:Map},{id:'led',label:'LED / 音声',icon:SlidersHorizontal},{id:'usb',label:'USB',icon:Usb},{id:'system',label:'システム',icon:Monitor,group:'MANAGE'},{id:'logs',label:'ログ',icon:Database},{id:'settings',label:'設定・バックアップ',icon:Settings2}]
const page=ref(location.hash.slice(1)||'dashboard'), mobile=ref(false), search=ref(''), advanced=ref(false), loading=ref(false), logged=ref(false), booting=ref(true), error=ref(''), notice=ref(''), connected=ref(false)
const summary=ref<Summary>({}),caps=ref<Capability[]>([]),settings=ref<Settings>({revision:1,theme:'system',locale:'ja',favorites:['system','network','storage']}),logs=ref(''), files=ref<FileEntry[]>([]),path=ref('.'),fileSearch=ref(''), selectedVideo=ref('')
const cameraSource=ref('front'),cameraColor=ref('auto'),cameraID=ref(''),imageURL=ref(''),cameraError=ref(''),cameraBusy=ref(false)
const dialog=ref<'logout'|'settings'|'camera'|''>(''),restoreFile=ref<Settings|null>(null),restoreDiff=ref<unknown>(),themeDraft=ref('system')
const vpnURL=ref(''),vpnBusy=ref(false)
let events:EventSource|undefined,reconnect:ReturnType<typeof setTimeout>|undefined, backoff=2000,cameraTimer:ReturnType<typeof setTimeout>|undefined, objectURL=''
const title=computed(()=>nav.find(n=>n.id===page.value)?.label||'ダッシュボード'),filteredNav=computed(()=>nav.filter(n=>n.label.toLowerCase().includes(search.value.toLowerCase())))
const uptime=computed(()=>{const n=summary.value.uptime?.data;if(typeof n!=='number')return '—';const h=Math.floor(n/3600),m=Math.floor(n%3600/60);return h>=24?`${Math.floor(h/24)}日 ${h%24}時間`:`${h}時間 ${m}分`})
const services=computed(()=>summary.value.services?.data as {name:string;state:string}[]|undefined)
const activeServices=computed(()=>services.value?.filter(s=>s.state==='active').length)
const traffic=computed(()=>summary.value.traffic?.data as {interface:string;rxBytes:string;txBytes:string}[]|undefined)
const temp=computed(()=>{const a=summary.value.temperatures?.data as {name:string;celsius:number;source:string}[]|undefined;return a?.filter(t=>t.name.toLowerCase().includes('cpu')).slice(0,4)||a?.slice(0,4)||[]})
const fileList=computed(()=>files.value.filter(f=>f.name.toLowerCase().includes(fileSearch.value.toLowerCase())))
const subtitle:Record<string,string>={dashboard:'端末とネットワークの状態を確認できます。',internet:'LTE、Wi-Fi、インターネット疎通は個別に確認します。',wifi:'純正の通信制御を維持しながら、接続状態を読み取ります。',traffic:'インターフェースごとの実測カウンタ。表示値は起動後の累計です。',camera:'前方・車内のライブ映像を表示します。',recordings:'SDカードの原本を閲覧・ダウンロードできます。',storage:'SDカードへの操作は読み取り専用です。',trips:'走行経路と電波品質を、同じ地図で。',system:'純正サービスの稼働状況と端末の実測値。',settings:'表示設定と、資格情報を含めない設定バックアップ。',logs:'この管理画面での操作履歴。映像・位置・資格情報は記録しません。'}
function go(id:string){page.value=id;location.hash=id;mobile.value=false}
function message(e:unknown){return e instanceof Error?e.message:String(e)}
async function refresh(){try{summary.value=await api<Summary>('/system/summary');connected.value=true;error.value=''}catch(e){connected.value=false;error.value=message(e);if(error.value.startsWith('401:')){logged.value=false;closeEvents();await stopCamera()}}}
async function init(){await Promise.all([refresh(),api<Capability[]>('/capabilities').then(v=>caps.value=v),api<Settings>('/settings').then(v=>{settings.value=v;themeDraft.value=v.theme})]);openEvents();await loadPage()}
function closeEvents(){events?.close();if(reconnect)clearTimeout(reconnect)}
function openEvents(){closeEvents();if(!logged.value)return;events=new EventSource('/api/v1/events');events.addEventListener('refresh',()=>{backoff=2000;refresh()});events.onerror=()=>{connected.value=false;events?.close();reconnect=setTimeout(openEvents,backoff);backoff=Math.min(backoff*2,60000)}}
async function logout(){try{await api('/auth/logout','POST')}catch{};logged.value=false;dialog.value='';closeEvents();await stopCamera();summary.value={};logs.value='';files.value=[];selectedVideo.value=''}
async function loadPage(){if(!logged.value)return;try{if(page.value==='storage'||page.value==='recordings'){path.value=page.value==='recordings'?'DRIVERECDATA':'.';await loadFiles(path.value)}if(page.value==='logs'){const r=await fetch('/api/v1/logs');if(!r.ok)throw new Error('操作履歴を取得できません');logs.value=await r.text()}}catch(e){error.value=message(e)}}
async function loadFiles(p:string){loading.value=true;selectedVideo.value='';try{const list=await api<FileEntry[]>('/storage/files?path='+encodeURIComponent(p));files.value=list;path.value=p}catch(e){error.value=message(e)}finally{loading.value=false}}
function up(){const parts=path.value.split('/');parts.pop();loadFiles(parts.join('/')||'.')}
function fileURL(p:string){return '/api/v1/storage/file?path='+encodeURIComponent(p)}
async function saveSettings(){loading.value=true;try{settings.value=await api<Settings>('/settings','PUT',{expectedRevision:settings.value.revision,settings:{...settings.value,theme:themeDraft.value}});notice.value='設定を保存しました';dialog.value=''}catch(e){error.value=message(e)}finally{loading.value=false}}
async function exportBackup(){try{const result=await api('/backup/export','POST');download(JSON.stringify(result,null,2),'ncc-settings.json','application/json');notice.value='表示設定をエクスポートしました'}catch(e){error.value=message(e)}}
function download(data:string,name:string,type:string){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function loginVPN(){vpnBusy.value=true;try{const v=await api<{authURL:string}>('/vpn/tailscale/login','POST');if(v.authURL){const u=new URL(v.authURL);if(u.protocol!=='https:'||u.hostname!=='login.tailscale.com')throw new Error('予期しない認証URLです');vpnURL.value=u.href}else{notice.value='Tailscale状態を再取得しました';await refresh()}}catch(e){error.value=message(e)}finally{vpnBusy.value=false}}
async function checkRestore(event:Event){try{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>16000)throw new Error('バックアップが大きすぎます');const value=JSON.parse(await file.text());if(value.schemaVersion!==1)throw new Error('未対応のバックアップです');restoreFile.value=value.settings;restoreDiff.value=await api('/backup/restore','POST',{schemaVersion:1,expectedRevision:settings.value.revision,dryRun:true,settings:value.settings})}catch(e){error.value=message(e)}}
async function applyRestore(){try{settings.value=await api<Settings>('/backup/restore','POST',{schemaVersion:1,expectedRevision:settings.value.revision,dryRun:false,settings:restoreFile.value});themeDraft.value=settings.value.theme;restoreFile.value=null;restoreDiff.value=undefined;notice.value='表示設定を復元しました'}catch(e){error.value=message(e)}}
async function startCamera(){cameraBusy.value=true;cameraError.value='';try{const s=await api<{id:string}>('/camera/sessions','POST',{source:cameraSource.value,color:cameraColor.value});cameraID.value=s.id;await frame()}catch(e){cameraError.value=message(e)}finally{cameraBusy.value=false}}
async function switchCamera(){const active=!!cameraID.value;await stopCamera();if(active)await startCamera()}
async function frame(){if(!cameraID.value)return;try{const r=await fetch(`/api/v1/camera/sessions/${cameraID.value}/stream`);if(!r.ok)throw new Error(r.status===503?'カメラ出力が未取得、または古くなっています。':r.status===403?'配信セッションが終了しました。再度許可してください。':'画像を取得できません。');const blob=await r.blob();if(!cameraID.value)return;if(objectURL)URL.revokeObjectURL(objectURL);objectURL=URL.createObjectURL(blob);imageURL.value=objectURL;cameraTimer=setTimeout(frame,1000)}catch(e){cameraError.value=message(e);await stopCamera()}}
async function stopCamera(){if(cameraTimer)clearTimeout(cameraTimer);const id=cameraID.value;cameraID.value='';imageURL.value='';if(objectURL){URL.revokeObjectURL(objectURL);objectURL=''}if(id&&logged.value){try{await api(`/camera/sessions/${id}`,'DELETE')}catch{}}}
watch(page,async()=>{error.value='';if(page.value!=='camera')await stopCamera();await loadPage()})
watch(()=>settings.value.theme,v=>{document.documentElement.dataset.theme=v},{immediate:true})
watch(notice,v=>{if(v)setTimeout(()=>notice.value='',5000)})
onMounted(async()=>{window.addEventListener('hashchange',hashChange);try{const s=await api<{csrf:string}>('/auth/session');setCSRF(s.csrf);logged.value=true;await init()}catch(e){logged.value=true;error.value=message(e)}finally{booting.value=false}})
function hashChange(){page.value=location.hash.slice(1)||'dashboard'}
onUnmounted(()=>{window.removeEventListener('hashchange',hashChange);closeEvents();stopCamera()})
</script>

<template>
<div v-if="booting" class="boot"><span class="brand-mark">N</span><p>Control Center を開いています</p></div>
<div v-else-if="!logged" class="boot"><span class="brand-mark">N</span><p>端末への接続を確認しています</p><button class="secondary" @click="logged=true;init()">再接続</button></div>
<div v-else class="app-shell">
 <div v-if="mobile" class="backdrop" @click="mobile=false"></div>
 <aside class="sidebar" :class="{open:mobile}"><div class="device-label"><span class="tiny-led"></span>NP1 <span class="tag">LOCAL</span></div><label class="nav-search"><Search :size="15"/><input v-model="search" placeholder="メニューを検索" aria-label="メニューを検索"></label><nav><template v-for="n in filteredNav" :key="n.id"><span v-if="n.group&&!search" class="nav-group">{{n.group}}</span><a :href="'#'+n.id" :class="{active:page===n.id}" @click.prevent="go(n.id)"><component :is="n.icon" :size="17"/><span>{{n.label}}</span><ChevronRight v-if="page===n.id" class="active-arrow" :size="13"/></a></template><p v-if="!filteredNav.length" class="hint">該当するメニューはありません</p></nav><div class="sidebar-bottom"><ShieldCheck :size="17"/><div>ネットワーク認証<small>ホットスポット / Tailscale</small></div></div></aside>
 <div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" @click="mobile=true" aria-label="メニューを開く"><Menu :size="20"/></button><span>Control Center</span><ChevronRight :size="13"/><strong>{{title}}</strong></div><div class="top-actions"><span class="connection" :class="{offline:!connected}"><i></i>{{connected?'実機データ受信中':'接続を確認中'}}</span><button class="icon-button" @click="refresh" aria-label="状態を更新"><RefreshCw :size="17"/></button></div></header>
 <main class="main-content"><div class="page-heading"><div><span class="eyebrow">NP1 / {{page==='dashboard'?'OVERVIEW':page.toUpperCase()}}</span><h1>{{title}}</h1><p>{{subtitle[page]||'取得可能な情報と、実機での対応状況を確認できます。'}}</p></div><button class="secondary compact advanced" @click="advanced=!advanced"><SlidersHorizontal :size="15"/>{{advanced?'詳細表示':'簡易表示'}}</button></div>
 <div v-if="error" class="banner error" role="alert"><CircleHelp :size="17"/><span>{{error}}</span><button class="icon-button" @click="error=''" aria-label="通知を閉じる"><X :size="15"/></button></div><div v-if="notice" class="banner success" role="status"><Check :size="17"/>{{notice}}</div>

 <template v-if="page==='dashboard'">
 <section class="overview-strip"><div><span class="eyebrow">DEVICE UPTIME</span><strong>{{uptime}}</strong><span class="muted">前回の起動から</span></div><div><span class="eyebrow">STOCK SERVICES</span><strong>{{activeServices??'—'}}<small> / {{services?.length??'—'}}</small></strong><span class="muted">純正サービス active</span></div><div><span class="eyebrow">WIFI STATION</span><strong class="medium">{{summary.wifi?.data?.wpa_state==='COMPLETED'?'接続済み':'未確認'}}</strong><span class="muted">インターネット疎通は別途確認</span></div><div><span class="eyebrow">USB MODE</span><strong class="medium">{{summary.usb?.data||'—'}}</strong><span class="muted">{{summary.usb?.data==='peripheral'?'USBデバイスとして動作':'取得したroleを表示'}}</span></div></section>
 <div class="section-label"><h2>ネットワーク</h2><button class="text-button" @click="go('internet')">詳細を見る<ArrowUpRight :size="14"/></button></div>
 <div class="card-grid three"><ObservationCard title="LTE / モデム" :observation="summary.modem"/><ObservationCard title="Wi-Fi STA" :observation="summary.wifi"><div class="wifi-summary"><Wifi :size="30" stroke-width="1.4"/><strong>{{summary.wifi?.data?.wpa_state==='COMPLETED'?'接続済み':summary.wifi?.data?.wpa_state||'—'}}</strong></div><dl class="details"><div><dt>アドレス</dt><dd>{{summary.wifi?.data?.ip_address||'未取得'}}</dd></div><div><dt>周波数</dt><dd>{{summary.wifi?.data?.freq?`${summary.wifi.data.freq} MHz`:'未取得'}}</dd></div><div><dt>認証</dt><dd>{{summary.wifi?.data?.key_mgmt||'未取得'}}</dd></div></dl></ObservationCard><ObservationCard title="ローカルAP" :observation="summary.hotspot"/></div>
 <div class="dashboard-bottom"><section class="panel"><div class="panel-head"><h2>純正サービス</h2><span class="tag">READ ONLY</span></div><div v-for="s in services" :key="s.name" class="service-row"><span class="service-icon"><Monitor :size="15"/></span><span>{{s.name.replace('app-@','').replace('.service','')}}</span><span class="state-text" :class="{good:s.state==='active'}"><i></i>{{s.state}}</span></div><p v-if="!services" class="empty-line">サービス状態を取得していません</p><div class="panel-footer"><ShieldCheck :size="14"/>純正サービスの停止・再起動は行いません</div></section><section class="panel device-panel"><div class="panel-head"><h2>デバイス</h2><button class="text-button" @click="go('system')"><ArrowUpRight :size="16"/></button></div><dl class="details"><div><dt>カーネル</dt><dd>{{summary.kernel?.data||'—'}}</dd></div><div><dt>microSD</dt><dd>{{summary.sd?.status==='available'?'マウント済み':'未取得'}}</dd></div><div><dt>ファイルシステム</dt><dd>{{summary.sd?.data?.filesystem||'—'}}</dd></div><div><dt>Tailscale</dt><dd>{{summary.tailscale?.data?.backendState||'未取得'}}</dd></div></dl><div class="subsection"><span class="eyebrow">TEMPERATURE / SOC</span><div class="temperature-list"><div v-for="t in temp" :key="t.name"><strong>{{t.celsius.toFixed(1)}}<small>°C</small></strong><span>{{t.name}}</span></div><p v-if="!temp.length" class="hint">温度未取得</p></div><p class="hint">SoCセンサーの実測値です。外気温ではありません。</p></div><button class="library-link" @click="go('recordings')"><span class="library-icon"><Video :size="22"/></span><span><strong>録画ライブラリ</strong><small>SDカードの録画を確認</small></span><ArrowUpRight :size="18"/></button></section></div>
 </template>

 <template v-else-if="page==='internet'||page==='wifi'"><div class="card-grid two"><ObservationCard title="LTE / APN" :observation="summary.modem"/><ObservationCard title="インターネット疎通" :observation="summary.internet"/><ObservationCard title="Wi-Fi STA" :observation="summary.wifi"><dl class="details"><div v-for="(v,k) in summary.wifi?.data" :key="k"><dt>{{k}}</dt><dd>{{v}}</dd></div></dl></ObservationCard><ObservationCard title="ホットスポット" :observation="summary.hotspot"/></div><section class="panel space-top"><div class="panel-head"><h2>ルーティング</h2><span class="tag">READ ONLY</span></div><pre>{{summary.routes?.data||'未取得'}}</pre><p class="hint pad">常時AP / AP+STA / APNの変更は、純正IPCと復旧経路の検証後に有効化します。</p></section><section v-if="page==='internet'" class="panel space-top"><div class="panel-head"><h2>Tailscale / 遠隔アクセス</h2><span class="tag">OPTIONAL</span></div><div class="settings-body"><dl class="details full"><div><dt>Backend</dt><dd>{{summary.tailscale?.data?.backendState||'未導入・未取得'}}</dd></div><div><dt>接続</dt><dd>{{summary.tailscale?.data?.online===true?'Online':summary.tailscale?.data?.online===false?'Offline':'未確認'}}</dd></div><div><dt>Tailscale IP</dt><dd>{{summary.tailscale?.data?.ips?.join(', ')||'未割当'}}</dd></div></dl><p class="hint">DNSの変更・他ネットワークのルート受入・SSH・サブネット広告は無効です。遠隔Web到達はtailnet認証後に検証します。</p><button class="secondary" :disabled="vpnBusy||summary.tailscale?.status!=='available'" @click="loginVPN">{{vpnBusy?'認証を準備しています…':'Tailscaleの認証を開始'}}<ArrowUpRight :size="15"/></button><a v-if="vpnURL" :href="vpnURL" target="_blank" rel="noreferrer" class="primary">Tailscaleでログインする<ArrowUpRight :size="15"/></a></div></section></template>

 <template v-else-if="page==='traffic'"><section class="panel"><div class="panel-head"><h2>インターフェース別の通信量</h2><span class="tag">起動後の累計</span></div><div class="table-wrap"><table><thead><tr><th>インターフェース</th><th>受信</th><th>送信</th><th>計測元</th></tr></thead><tbody><tr v-for="t in traffic" :key="t.interface"><td class="mono">{{t.interface}}</td><td>{{bytes(t.rxBytes)}}</td><td>{{bytes(t.txBytes)}}</td><td class="muted">/proc/net/dev</td></tr></tbody></table></div></section><p class="hint">カウンタは64bitの10進文字列で転送します。日次・月次の永続集計とLTEインターフェースの特定は未検証です。</p></template>

 <template v-else-if="page==='storage'||page==='recordings'"><div class="file-toolbar"><button class="secondary compact" :disabled="path==='.'||loading" @click="up"><ArrowUp :size="15"/>上へ</button><span class="mono breadcrumb-path">SD / {{path==='.'?'':path}}</span><label class="file-search"><Search :size="16"/><input v-model="fileSearch" placeholder="このフォルダーを検索" aria-label="ファイルを検索"></label></div><section class="panel"><div class="panel-head"><h2>{{page==='recordings'?'録画ファイル':'ファイル'}}</h2><span class="muted">最大300件 · 読み取り専用</span></div><div class="table-wrap"><table><thead><tr><th>名前</th><th>更新日時</th><th>サイズ</th><th>操作</th></tr></thead><tbody><tr v-for="f in fileList" :key="f.path"><td><button v-if="f.directory" class="file-name" @click="loadFiles(f.path)"><Folder :size="17"/>{{f.name}}<ChevronRight :size="14"/></button><span v-else class="file-name"><Video v-if="f.media==='video-candidate'" :size="17"/><HardDrive v-else :size="17"/>{{f.name}}</span></td><td class="muted nowrap">{{date(f.modified)}}</td><td class="mono nowrap">{{f.directory?'—':bytes(f.size)}}</td><td><div v-if="!f.directory" class="file-actions"><button v-if="f.media==='video-candidate'" class="text-button" @click="selectedVideo=fileURL(f.path)">再生</button><a :href="fileURL(f.path)" :download="f.name" class="icon-button" aria-label="原本をダウンロード"><Download :size="16"/></a></div></td></tr><tr v-if="!fileList.length"><td colspan="4" class="empty-line">{{loading?'読み込み中…':'ファイルがありません'}}</td></tr></tbody></table></div></section><section v-if="selectedVideo" class="panel space-top"><div class="panel-head"><h2>録画プレビュー</h2><button class="icon-button" @click="selectedVideo=''" aria-label="プレイヤーを閉じる"><X :size="17"/></button></div><video :src="selectedVideo" controls preload="metadata" class="recording-player"></video><p class="hint pad">ブラウザー非対応のコンテナ・コーデックは原本をダウンロードしてください。拡張子だけで形式を確定しません。</p></section><p class="hint">索引・時刻同期・録画中ファイル判定は開発中です。削除・移動・フォーマットは提供していません。</p></template>

 <template v-else-if="page==='camera'"><section class="panel camera-panel"><div class="panel-head"><h2>{{cameraSource==='front'?'前方カメラ':'車内カメラ'}}</h2><span class="tag">640 × 360 · 最大 1 fps · JPEG</span></div><div class="camera-preview"><img v-if="imageURL" :src="imageURL" alt="ライブカメラ映像"><div v-else><Camera :size="40" stroke-width="1"/><h3>カメラは停止しています</h3><p>表示ボタンでライブ映像を開きます。</p></div></div><div class="camera-controls"><select v-model="cameraSource" aria-label="カメラを選択" @change="switchCamera"><option value="front">前方カメラ</option><option value="in">車内カメラ</option></select><select v-model="cameraColor" aria-label="映像の色調" @change="switchCamera"><option value="auto">色調: 自動補正</option><option value="source">色調: 元映像</option></select><button v-if="!cameraID" class="primary" @click="startCamera" :disabled="cameraBusy"><Camera :size="16"/>映像を表示</button><button v-else class="secondary" @click="stopCamera"><X :size="16"/>表示を停止</button><span class="hint">閲覧中だけ更新します。</span></div><p v-if="cameraError" class="error pad" role="alert">{{cameraError}}</p></section></template>

 <template v-else-if="page==='trips'"><section class="panel radio-panel"><RadioMap/></section><div class="banner neutral space-top"><ShieldCheck :size="18"/><span>ロガーは未有効です。位置情報の収集・保持・外部送信には個別の許可が必要です。</span></div></template>

 <template v-else-if="page==='system'"><section class="overview-strip"><div><span class="eyebrow">UPTIME</span><strong>{{uptime}}</strong></div><div><span class="eyebrow">KERNEL</span><strong class="medium mono">{{summary.kernel?.data||'—'}}</strong></div><div><span class="eyebrow">LOAD AVERAGE</span><strong class="medium mono">{{String(summary.load?.data||'—').split(' ').slice(0,3).join(' / ')}}</strong></div></section><section class="panel space-top"><div class="panel-head"><h2>純正サービス</h2></div><div v-for="s in services" :key="s.name" class="service-row"><Monitor :size="16"/><span class="mono">{{s.name}}</span><span class="state-text" :class="{good:s.state==='active'}"><i></i>{{s.state}}</span></div></section><section class="panel space-top"><div class="panel-head"><h2>メモリ</h2><span class="tag">/proc/meminfo</span></div><pre>{{advanced?summary.memory?.data:String(summary.memory?.data||'').split('\n').slice(0,4).join('\n')}}</pre></section></template>

 <template v-else-if="page==='led'||page==='usb'"><ObservationCard :title="page==='led'?'LED状態':'USB role'" :observation="summary[page==='led'?'led':'usb']"><pre>{{summary[page==='led'?'led':'usb']?.data}}</pre></ObservationCard><div class="banner neutral space-top"><ShieldCheck :size="18"/><span>{{page==='led'?'純正表示の復元と競合回避を検証するまで、LEDの書込み・音量変更は無効です。':'USB host切替はADBを切断します。独立した管理経路と自動復帰を検証するまで切替は無効です。'}}</span></div></template>

 <template v-else-if="page==='logs'"><section class="panel"><div class="panel-head"><h2>操作履歴</h2><button class="text-button" @click="loadPage"><RefreshCw :size="14"/>更新</button></div><pre class="audit-log">{{logs||'まだ操作履歴がありません'}}</pre></section></template>

 <template v-else-if="page==='settings'"><div class="card-grid two"><section class="panel"><div class="panel-head"><h2>表示設定</h2><span class="muted">rev. {{settings.revision}}</span></div><div class="settings-body"><label>テーマ<select v-model="themeDraft"><option value="system">システムに合わせる</option><option value="light">ライト</option><option value="dark">ダーク</option></select></label><p class="hint">言語: 日本語。英語は今後対応予定です。</p><button class="primary" @click="dialog='settings'" :disabled="themeDraft===settings.theme">変更を確認</button></div></section><section class="panel"><div class="panel-head"><h2>設定バックアップ</h2><ShieldCheck :size="17"/></div><div class="settings-body"><p>対象は表示設定です。認証情報・TLS秘密鍵・Tailscale state・位置・映像・純正設定は含みません。</p><button class="secondary" @click="exportBackup"><Download :size="16"/>エクスポート</button><label class="upload-label">バックアップを検証<input type="file" accept="application/json,.json" @change="checkRestore"></label><template v-if="restoreDiff"><pre>{{restoreDiff}}</pre><button class="primary" @click="applyRestore">この差分で復元する</button></template></div></section></div><section class="panel space-top"><div class="panel-head"><h2>機能の対応状況</h2><span class="tag">実機の検証状況</span></div><div class="table-wrap"><table><thead><tr><th>機能</th><th>状態</th><th>確認内容・制限</th></tr></thead><tbody><tr v-for="c in caps" :key="c.id"><td class="mono">{{c.id}}</td><td><span class="status" :class="c.status"><i></i>{{c.status==='available'?'読み取り可能':c.status==='unsupported'?'非対応':'未検証'}}</span></td><td>{{c.reason}}</td></tr></tbody></table></div></section></template>
 <template v-else><section class="panel empty-state"><Users :size="36" stroke-width="1"/><h2>実機の取得経路を調査しています</h2><p>DHCP lease・接続端末の取得方法を確認するまで、推定した端末一覧は表示しません。</p><button class="secondary" @click="go('settings')">対応状況を見る<ArrowUpRight :size="15"/></button></section></template>
 <div v-if="advanced" class="panel space-top"><div class="panel-head"><h2>取得メタデータ</h2><span class="tag">SOURCE / FRESHNESS</span></div><div class="table-wrap"><table><thead><tr><th>項目</th><th>状態</th><th>更新日時</th><th>取得元</th></tr></thead><tbody><tr v-for="(o,k) in summary" :key="k"><td>{{k}}</td><td>{{o.status}}</td><td class="nowrap">{{date(o.observedAt)}}</td><td>{{o.source}}</td></tr></tbody></table></div></div>
 <footer class="page-footer"><span>NP1 Control Center <span class="version">0.1 · DEVELOPMENT</span></span><span>ローカルで動作 · 未検証の操作は無効</span></footer>
 </main></div>
 <div v-if="dialog==='settings'" class="modal-backdrop" @click.self="dialog=''"><section class="modal" role="dialog" aria-modal="true" aria-label="表示設定の変更"><div class="modal-title"><h2>表示設定を変更</h2><button class="icon-button" @click="dialog=''" aria-label="閉じる"><X :size="20"/></button></div><dl class="details"><div><dt>テーマ</dt><dd>{{settings.theme}} → {{themeDraft}}</dd></div></dl><button class="primary" @click="saveSettings" :disabled="loading">変更を適用</button></section></div>
</div>
</template>
